1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	  enchantment?: number;
9	  material?: string;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
14	const LOYALTY_DISCOUNT_RATE = 0.2;
15	const LOYALTY_YEARS_THRESHOLD = 2;
16	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
17	
18	const INSURANCE_VALUES: Record<string, number> = {
19	  sword: 1000,
20	  amulet: 600,
21	  staff: 800,
22	  potion: 400,
23	  rune: 250,
24	  moonstone: 250,
25	};
26	
27	const DEDUCTIBLE_PER_DAMAGE = 100;
28	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	// The single place that knows how the item catalogue is stored; pricing
40	// policies ask it for a type's listed base premium rather than indexing.
41	function listedBasePremium(type: string): number {
42	  return BASE_PREMIUMS[type];
43	}
44	
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const COMPONENT_BLOCK_SIZE = 3;
49	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
50	
51	// "Alike" means the same item type: 2 runes + 1 moonstone form no block,
52	// while 3 runes + 3 moonstones form two separate blocks.
53	function groupAlikeItems(items: Item[]): Map<string, number> {
54	  const countsPerAlikeGroup = new Map<string, number>();
55	  for (const item of items) {
56	    countsPerAlikeGroup.set(item.type, (countsPerAlikeGroup.get(item.type) ?? 0) + 1);
57	  }
58	  return countsPerAlikeGroup;
59	}
60	
61	function qualifiesForComponentBlock(count: number): boolean {
62	  return count === COMPONENT_BLOCK_SIZE;
63	}
64	
65	function basePremiumForAlikeGroup(type: string, count: number): number {
66	  if (qualifiesForComponentBlock(count)) {
67	    return COMPONENT_BLOCK_BASE_PREMIUM;
68	  }
69	  return count * listedBasePremium(type);
70	}
71	
72	function isHighlyEnchanted(item: Item): boolean {
73	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
74	}
75	
76	// Item-specific modifiers apply to the base premium of the affected item,
77	// not to the policy total.
78	function itemSurcharges(item: Item): number {
79	  const itemBasePremium = listedBasePremium(item.type);
80	  let surcharges = 0;
81	  if (item.cursed === true) {
82	    surcharges += itemBasePremium * CURSE_SURCHARGE_RATE;
83	  }
84	  if (isHighlyEnchanted(item)) {
85	    surcharges += itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
86	  }
87	  return surcharges;
88	}
89	
90	// The spec's "policy base premium": the sum of all item base premiums,
91	// before any item-specific or policy-wide modifier.
92	function policyBasePremium(items: Item[]): number {
93	  let total = 0;
94	  for (const [type, count] of groupAlikeItems(items)) {
95	    total += basePremiumForAlikeGroup(type, count);
96	  }
97	  return total;
98	}
99	
100	function totalItemSurcharges(items: Item[]): number {
101	  return items.reduce((total, item) => total + itemSurcharges(item), 0);
102	}
103	
104	// How the customer stands with MHPCO when this policy is quoted. Loyalty and
105	// the follow-up discount both read this one history, so it travels as one value.
106	interface CustomerStanding {
107	  yearsWithMHPCO: number;
108	  previousContracts: number;
109	}
110	
111	function isLongStanding(standing: CustomerStanding): boolean {
112	  return standing.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
113	}
114	
115	// The spec's "each contract after their first": keyed on the customer's
116	// contract history, not on anything about this policy's items.
117	function isFollowUpContract(standing: CustomerStanding): boolean {
118	  return standing.previousContracts > 0;
119	}
120	
121	// Discounts MHPCO grants for who the customer is. Changes whenever MHPCO
122	// revises how it rewards customer history.
123	function customerStandingDiscounts(standing: CustomerStanding, basePremium: number): number {
124	  let discounts = 0;
125	  if (isLongStanding(standing)) {
126	    discounts += basePremium * LOYALTY_DISCOUNT_RATE;
127	  }
128	  if (isFollowUpContract(standing)) {
129	    discounts += basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
130	  }
131	  return discounts;
132	}
133	
134	// Every quote newly assesses the items it covers, so this surcharge applies to
135	// each policy regardless of the customer's standing (see the spec's second
136	// integration example). Changes independently of the history-based discounts.
137	function firstInsuranceSurcharge(basePremium: number): number {
138	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
139	}
140	
141	function roundPremiumInMHPCOsFavour(premium: number): number {
142	  return Math.ceil(premium);
143	}
144	
145	export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
146	  const standing: CustomerStanding = { ...customer, previousContracts };
147	  const basePremium = policyBasePremium(items);
148	  // Policy-wide modifiers are percentages of the policy base premium itself,
149	  // not of the premium already raised by item-specific surcharges.
150	  const premium =
151	    basePremium +
152	    totalItemSurcharges(items) +
153	    firstInsuranceSurcharge(basePremium) -
154	    customerStandingDiscounts(standing, basePremium) +
155	    PROCESSING_FEE;
156	  return roundPremiumInMHPCOsFavour(premium);
157	}
158	
159	function insuranceSum(items: Item[]): number {
160	  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
161	}
162	
163	function roundPayoutInMHPCOsFavour(payout: number): number {
164	  return Math.floor(payout);
165	}
166	
167	// A deductible applies per damage event, so each damaged item is reimbursed
168	// separately before the policy cap is applied.
169	function reimbursementForDamage(damage: Damage): number {
170	  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
171	}
172	
173	function reimbursementForIncident(incident: Incident): number {
174	  return incident.damages.reduce((total, damage) => total + reimbursementForDamage(damage), 0);
175	}
176	
177	export interface Damage {
178	  itemType: string;
179	  amount: number;
180	}
181	
182	export interface Incident {
183	  cause: string;
184	  damages: Damage[];
185	}
186	
187	export interface QuoteStep {
188	  op: "quote";
189	  items: Item[];
190	}
191	
192	export interface ClaimStep {
193	  op: "claim";
194	  policy: number;
195	  incident: Incident;
196	}
197	
198	export type Step = QuoteStep | ClaimStep;
199	
200	export interface Scenario {
201	  customer: Customer;
202	  steps: Step[];
203	}
204	
205	export interface QuoteResult {
206	  premium: number;
207	}
208	
209	export interface ClaimResult {
210	  payout: number;
211	  remainingCap: number;
212	}
213	
214	export type StepResult = QuoteResult | ClaimResult;
215	
216	interface Policy {
217	  items: Item[];
218	  remainingCap: number;
219	}
220	
221	function openPolicy(items: Item[]): Policy {
222	  return { items, remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM };
223	}
224	
225	// The cap decision, independent of which claim clauses produced the
226	// reimbursement: MHPCO never pays more than the policy's remaining cap, and
227	// whatever it pays is consumed from that cap.
228	function payoutAllowedByCap(reimbursement: number, remainingCap: number): ClaimResult {
229	  const payout = roundPayoutInMHPCOsFavour(Math.min(reimbursement, remainingCap));
230	  return { payout, remainingCap: remainingCap - payout };
231	}
232	
233	// Settling a claim composes two independently changing decisions: what the
234	// claim clauses reimburse, and how much of that the policy cap still allows.
235	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
236	  return payoutAllowedByCap(reimbursementForIncident(incident), policy.remainingCap);
237	}
238	
239	// Scenario bookkeeping, not a claim-office rule: a claim step names its policy
240	// by the zero-based index of the quote step that opened it, and the customer's
241	// contract history grows as the scenario concludes contracts.
242	class PolicyRegister {
243	  private readonly byOpeningStep = new Map<number, Policy>();
244	  private concluded = 0;
245	
246	  get contractsConcluded(): number {
247	    return this.concluded;
248	  }
249	
250	  record(openingStep: number, policy: Policy): void {
251	    this.byOpeningStep.set(openingStep, policy);
252	    this.concluded += 1;
253	  }
254	
255	  // Owns the policy's running cap: settling a claim against a registered policy
256	  // is the only way its remaining cap changes.
257	  settleAgainst(openingStep: number, incident: Incident): ClaimResult {
258	    const policy = this.policyOpenedBy(openingStep);
259	    const settlement = settleClaim(policy, incident);
260	    policy.remainingCap = settlement.remainingCap;
261	    return settlement;
262	  }
263	
264	  private policyOpenedBy(openingStep: number): Policy {
265	    const policy = this.byOpeningStep.get(openingStep);
266	    if (policy === undefined) {
267	      throw new Error(`claim refers to step ${String(openingStep)}, which created no policy`);
268	    }
269	    return policy;
270	  }
271	}
272	
273	export function runScenario(scenario: Scenario): { results: StepResult[] } {
274	  const register = new PolicyRegister();
275	  const results = scenario.steps.map((step, index): StepResult => {
276	    if (step.op === "quote") {
277	      const premium = quote(scenario.customer, step.items, register.contractsConcluded);
278	      register.record(index, openPolicy(step.items));
279	      return { premium };
280	    }
281	    return register.settleAgainst(step.policy, step.incident);
282	  });
283	  return { results };
284	}
