cp src/claim-office.ts /tmp/co.bak && python3 - <<'EOF'
import re
p='src/claim-office.ts'
s=open(p).read()

old_ins = """const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// The single place that knows how the item catalogue is stored; pricing
// policies ask it for a type's listed base premium rather than indexing.
function listedBasePremium(type: string): number {
  return BASE_PREMIUMS[type];
}
"""

new_ins = """// The MHPCO price list: one row per insurable item type, stating that type's
// insurance value and base premium. The spec lists both figures together
// ("Amulet: 600 G / 60 G"), and the set of rows is one piece of knowledge --
// a type MHPCO will not price is a type it will not insure.
interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: { insuranceValue: 250, basePremium: 25 },
  moonstone: { insuranceValue: 250, basePremium: 25 },
};

// The only two places that know how the price list is stored; pricing and
// claim policies ask for a type's listed figure rather than indexing.
function listedBasePremium(type: string): number {
  return PRICE_LIST[type].basePremium;
}

function listedInsuranceValue(type: string): number {
  return PRICE_LIST[type].insuranceValue;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
"""
assert old_ins in s
s=s.replace(old_ins,new_ins)

old_sum="  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);"
new_sum="  return items.reduce((sum, item) => sum + listedInsuranceValue(item.type), 0);"
assert old_sum in s
s=s.replace(old_sum,new_sum)
open(p,'w').write(s)
EOF
npx vitest run 2>&1 | tail -6 && npx tsc --noEmit && npx eslint src && echo GATES_OK

